import { test, expect } from '@playwright/test';

test.describe('File Upload - Title and Description', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully set title and description for an uploaded file', async ({ page }) => {
    // Upload file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Wait for file to appear in list
    const fileItem = page.getByRole('region', { name: /sample.pdf/i });
    await expect(fileItem).toBeVisible();

    // Set title
    const titleInput = page.getByLabel('File title');
    await titleInput.fill('Playwright Test Document');

    // Set description
    const descriptionInput = page.getByLabel('File description');
    await descriptionInput.fill('A PDF generated by Playwright for QA testing.');

    // Verify title and description are set
    await expect(fileItem).toContainText('Playwright Test Document');
    await expect(fileItem).toContainText('A PDF generated by Playwright for QA testing.');

    // Verify save button is enabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeEnabled();

    // Click save
    await saveButton.click();

    // Verify success message
    const successMessage = page.getByText(/file saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file is in list with metadata
    await expect(fileItem).toContainText('Playwright Test Document');
    await expect(fileItem).toContainText('Description: A PDF generated by Playwright for QA testing.');
  });

  test('should handle empty title and description fields with validation', async ({ page }) => {
    // Upload file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Wait for file to appear in list
    const fileItem = page.getByRole('region', { name: /sample.pdf/i });
    await expect(fileItem).toBeVisible();

    // Attempt to save without filling title or description
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify validation error appears for title
    const titleError = page.getByText(/title is required/i);
    await expect(titleError).toBeVisible();

    // Verify validation error appears for description
    const descriptionError = page.getByText(/description is required/i);
    await expect(descriptionError).toBeVisible();

    // Verify save button remains enabled but errors are visible
    await expect(saveButton).toBeEnabled();

    // Fill only title
    const titleInput = page.getByLabel('File title');
    await titleInput.fill('Only Title');

    // Verify description error persists
    await expect(descriptionError).toBeVisible();

    // Verify save button is still disabled due to missing description
    await expect(saveButton).toBeDisabled();

    // Clear title and verify both errors reappear
    await titleInput.clear();
    await expect(titleError).toBeVisible();
    await expect(descriptionError).toBeVisible();
  });
});
